// generar_317_fix_calendario_futuro_y_peso_vet.js
// CHIQUI Entre Señales — Cierre de dos bugs que quedaron a medias
//
// BUG 1 — Registrar en fecha futura (calendario), caso del swipe:
//   El fix anterior (315) reseteaba el día al navegar, pero se colaba:
//   con un día marcado (ej. 16 de julio) y avanzando al mes siguiente,
//   ese mismo número quedaba registrable aunque fuera futuro. La causa
//   era una comparación de fechas que incluía la HORA (hoy con hora
//   avanzada vs. día futuro a medianoche).
//   Ahora la validación compara SOLO fechas (a medianoche), con una
//   función única "esDiaFuturo" que usan tanto la grilla como el panel
//   de registro. Así, aunque un día se arrastre por swipe o flechas, si
//   su fecha en el mes/año actual es futura, el panel NO se abre. Cierra
//   el hueco por cualquier camino, sin depender del reset.
//
// BUG 2 — Peso de cachorros en el link del veterinario:
//   El fix del peso (315) se aplicó al componente de Salud, pero la
//   vista del veterinario (/vet) arma su propio resumen clínico aparte,
//   así que seguía marcando el aumento de peso de un cachorro como
//   observación (amarillo). Ahora el resumen clínico del vet también
//   considera la edad: en perros < 18 meses y gatos < 12, el aumento de
//   peso se informa en verde ("acorde a su crecimiento"), no como
//   observación. La pérdida de peso sigue marcándose igual.
//
// Archivos:
//   · app/calendario/page.tsx  (validación de fecha infalible)
//   · app/vet/page.tsx          (peso según edad en el resumen clínico)
//
// No hay SQL.
//
// Uso:
//   node generar_317_fix_calendario_futuro_y_peso_vet.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/calendario/page.tsx",
    base64: ""
  },
  {
    ruta: "app/vet/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
